def hgrid(size, orientation):
    """Create hollow square grid"""
    grid = [[0] * size for _ in range(size)]
    for r in range(size):
        for c in range(size):
            if r == 0 or r == size-1 or c == 0 or c == size-1:
                grid[r][c] = 1  # border
            else:
                grid[r][c] = 0  # hollow

    return grid

