def holo_grid(size, offset_r, offset_c):
    """Create pattern of given size with (offset_r, offset_c) = which corner gets the shape's top-left"""
    r_start, c_start = 0, 0
    if offset_r == 0:
        r_start = 0  # top
    elif offset_r == 1:
        r_start = size - 1  # bottom
    if offset_c == 0:
        c_start = 0  # left
    elif offset_c == 1:
        c_start = size - 1  # right

    for r in range(size):
        for c in range(size):
            global grid
            global r_start, c_start
            # The shape's row r, col c maps to grid row r_start+r, col c_start+c
            if r == 0 or r == size-1 or c == 0 or c == size-1:
                grid[2 + r_start + r][2 + c_start + c] = 5

